/* Shared editor feedback and useful paths between existing tools. */
(function(){'use strict';let saveKind='saved';const labels={saved:'Saved on device',saving:'Saving…',error:'Save needs attention',conflict:'Save conflict · keep a backup'};
function saveState(kind){saveKind=kind;const text=labels[kind]||kind;document.querySelectorAll('[data-save-label],#save-state').forEach(el=>{if(el.textContent.trim()!==text)el.textContent=text;el.dataset.saveKind=kind;});document.querySelectorAll('[data-editor-save-retry]').forEach(el=>el.hidden=kind!=='error');document.querySelectorAll('[data-editor-save-backup]').forEach(el=>el.hidden=!['error','conflict'].includes(kind));const strip=document.querySelector('#save-recovery');if(strip){strip.hidden=!['error','conflict'].includes(kind);strip.querySelector('[data-recovery-copy]').textContent=kind==='conflict'?'Another window saved changes. Keep a copy of this window before reloading.':'Your changes are still here. Retry saving or keep a backup.';strip.querySelector('[data-retry-save]').hidden=kind==='conflict';}}
function saveHTML(){return `<span class="editor-save-status" role="status" aria-live="polite"><span class="status-dot" aria-hidden="true"></span><span data-save-label data-save-kind="${saveKind}">${labels[saveKind]}</span><button type="button" id="editor-retry-save" data-editor-save-retry ${saveKind==='error'?'':'hidden'}>Retry saving</button><button type="button" id="editor-save-backup" data-editor-save-backup ${['error','conflict'].includes(saveKind)?'':'hidden'}>Keep a backup</button></span>`;}
function layer(title,copy){const modal=document.querySelector('.modal'),focus=document.activeElement;modal.inert=true;const overlay=document.createElement('div');overlay.className='choice-overlay';overlay.innerHTML=`<section class="choice-box connected-picker" role="dialog" aria-modal="true" aria-labelledby="connection-title"><h2 id="connection-title">${esc(title)}</h2>${copy}<button class="secondary" data-choice-cancel>Back to item</button></section>`;document.body.append(overlay);const close=()=>{modal.inert=false;overlay.remove();if(focus?.isConnected)focus.focus({preventScroll:true});};overlay.querySelector('[data-choice-cancel]').onclick=close;overlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}if(e.key==='Tab'){const f=[...overlay.querySelectorAll('button:not(:disabled),input,select,textarea')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});return {overlay,close};}
function openItem(id){const target=state.items.find(n=>n.id===id&&!n.deletedAt);if(!target){toast('This item is no longer available.');return;}activeEditor?.();closeModal();restoreWindow(target);editItem(target);}
function connections(item){activeEditor?.();const {overlay,close}=layer('Connected items',`<p class="hint">Keep related notes, plans and references within reach. Links work in both directions.</p><div data-connected-list></div><label class="field">Link an existing item<input id="connection-search" type="search" placeholder="Search item titles or tool names…" autocomplete="off"></label><div data-connection-candidates></div><p data-connection-status class="hint" role="status"></p>`),$=s=>overlay.querySelector(s);const render=()=>{const rows=NotaCohesion.connected(state.items,item),linked=new Set(rows.map(r=>r.item.id));$('[data-connected-list]').innerHTML=rows.length?rows.map(({item:n,manual})=>`<div class="connected-row"><button data-connected-open="${n.id}"><i data-lucide="${NotaCohesion.itemInfo(n).icon}"></i><span><strong>${esc(n.title||'Untitled item')}</strong><small>${esc(NotaCohesion.itemInfo(n).label)} · ${esc(state.workspaces.find(w=>w.id===n.workspace)?.name||'Canvas')}</small></span></button>${manual?`<button data-connected-remove="${n.id}" class="icon-button" aria-label="Remove connection to ${esc(n.title)}"><i data-lucide="unlink"></i></button>`:'<small class="connection-origin">Related</small>'}</div>`).join(''):'<p class="hint">No connections yet. Link an item below, or make a task from this writing.</p>';
 const q=NotaCohesion.normalize($('#connection-search').value),candidates=state.items.filter(n=>n.id!==item.id&&!n.deletedAt&&!linked.has(n.id)&&(!q||NotaCohesion.normalize([n.title,NotaCohesion.itemInfo(n).label,state.workspaces.find(w=>w.id===n.workspace)?.name].join(' ')).includes(q))).sort((a,b)=>Number(b.workspace===item.workspace)-Number(a.workspace===item.workspace)||String(b.updated).localeCompare(String(a.updated))).slice(0,8);$('[data-connection-candidates]').innerHTML=candidates.map(n=>`<button data-connect-item="${n.id}" class="connection-candidate"><i data-lucide="plus"></i><span><strong>${esc(n.title||'Untitled item')}</strong><small>${esc(NotaCohesion.itemInfo(n).label)} · ${esc(state.workspaces.find(w=>w.id===n.workspace)?.name||'Canvas')}</small></span></button>`).join('')||'<p class="hint">No matching items. Try another title.</p>';
 overlay.querySelectorAll('[data-connect-item]').forEach(b=>b.onclick=()=>{const target=state.items.find(n=>n.id===b.dataset.connectItem);try{NotaCohesion.link(item,target);touch(item);$('#connection-search').value='';render();$('[data-connection-status]').textContent='Connected. You can open either item to return to the other.';}catch(e){$('[data-connection-status]').textContent=e.message;}});overlay.querySelectorAll('[data-connected-remove]').forEach(b=>b.onclick=()=>{const target=state.items.find(n=>n.id===b.dataset.connectedRemove);NotaCohesion.unlink(item,target);touch(item);touch(target);render();$('[data-connection-status]').textContent='Connection removed. Both items are kept.';});overlay.querySelectorAll('[data-connected-open]').forEach(b=>b.onclick=()=>{close();openItem(b.dataset.connectedOpen);});icons();};$('#connection-search').oninput=render;render();$('#connection-search').focus();}
function selectedWriting(body){const field=writingDestination(body);if(!field)return '';if(field.isContentEditable){const sel=window.getSelection();return sel?.rangeCount&&field.contains(sel.anchorNode)&&field.contains(sel.focusNode)&&!sel.isCollapsed?sel.toString():plain(field.innerHTML);}return field.selectionStart!==field.selectionEnd&&field.selectionStart!==null?field.value.slice(field.selectionStart,field.selectionEnd):field.value;}
function makeTask(item,body,selection){activeEditor?.();const text=(selection??selectedWriting(body)).trim();const {overlay,close}=layer('Make it a task',`<p class="hint">Use the selected passage, or the writing field you were using. The task stays connected to this item.</p><label class="field">Task<textarea id="connected-task-text" rows="4" maxlength="2000" placeholder="A next step to remember…">${esc(text.slice(0,2000))}</textarea></label>${text.length>2000?'<p class="hint">The first 2,000 characters are shown. Shorten them to the next step you want to keep.</p>':''}<label class="field">Canvas<select id="connected-task-canvas">${canvasOptions(item.workspace).replace(/<option value="__new_canvas__">.*?<\/option>/,'')}</select></label><button class="primary" id="connected-task-create">Create connected task</button>`),field=overlay.querySelector('#connected-task-text'),button=overlay.querySelector('#connected-task-create');const validate=()=>button.disabled=!field.value.trim();field.oninput=validate;validate();button.onclick=()=>{const taskText=field.value.trim(),workspace=overlay.querySelector('#connected-task-canvas').value;if(!taskText)return;activeEditor?.();close();const child=addItem('task',{workspace,parentId:item.id,title:taskText.split('\n')[0].slice(0,120),tasks:[{id:uid(),text:taskText,done:false}]});touch(item);editItem(child);toast('Task created and connected to its source.');};field.focus();}
function install(item,body){const destination=body.querySelector('.editor-destination');if(destination){const button=document.createElement('button');button.id='editor-connections';button.className='secondary';button.innerHTML='<i data-lucide="link"></i> Connected items';button.onclick=()=>connections(item);destination.append(button);}const ai=body.querySelector('#note-ai,#mode-ai,#editor-companion'),snippets=body.querySelector('#editor-snippets'),group=document.createElement('section');group.className='editor-writing-tools';group.innerHTML='<h3>Work with this writing</h3><div class="editor-writing-actions"></div>';body.append(group);const actions=group.querySelector('div');if(ai)actions.append(ai);if(snippets)actions.append(snippets);const task=document.createElement('button');task.id='editor-make-task';task.className='secondary mode-assist';task.innerHTML='<i data-lucide="list-plus"></i> Make it a task';let selection;task.onpointerdown=()=>selection=selectedWriting(body);task.onclick=()=>{makeTask(item,body,selection);selection=undefined;};actions.append(task);}
window.NotaPolish={saveState,saveHTML,install,connections};
})();
